function locate(index){if(window.Workspace)Workspace.reveal('source');selected=index;const r=state.records[index];page=Math.floor(Math.max(0,browsingRecords().findIndex(x=>x.index===index))/pageSize);renderPreview();const rows=state.source.replace(/\r\n|\r/g,'\n').split('\n');const start=rows.slice(0,index).reduce((n,s)=>n+s.length+1,0);$('source').focus();$('source').setSelectionRange(start,start+r.raw.length);const lineHeight=parseFloat(getComputedStyle($('source')).lineHeight);$('source').scrollTop=Math.max(0,index*lineHeight-80);const role=C.resolve(state,r.roleId);if(role){roleQuery='';$('roleSearch').value='';roleLimit=state.roles.length;renderRoles();document.querySelector('[data-role="'+role.id+'"]')?.scrollIntoView({block:'nearest'});} }
