 const modelState=C.clone(state),editModel=C.bodyEditModel(modelState,modelState.records[index]);let editRefs=editModel.refs,editLast=$('editBody').value;if(editLast===r.body){$('editBody').value=editModel.body;editLast=editModel.body;}else editRefs=C.rebaseBodyReferences(editModel.body,editLast,editRefs);$('editBody').addEventListener('input',()=>{editRefs=C.rebaseBodyReferences(editLast,$('editBody').value,editRefs);editLast=$('editBody').value;});
 if(r.inputFormat==='tagged'&&r.type==='pending'&&C.partyCandidates(C.tagged(r.raw)).length){const button=document.createElement('button');button.id='choosePartyCandidate';button.textContent='选择小队姓名／职业候选';button.onclick=()=>partyCandidateDialog(index);$('modalBody').prepend(button);}
 $('editType').value=['action','dialogue','party','shout','yell','dice','dice','plain'].includes(r.type)?r.type:'action';
