 function collect(validate=true){editRefs=C.rebaseBodyReferences(editLast,$('editBody').value,editRefs);editLast=$('editBody').value;const type=$('editType').value,newName=$('newRole').value.trim(),newServer=$('newServer').value.trim(),id=$('editRole').value;if(validate&&type!=='plain'&&!id&&!newName){alert(uiText('message.bae93110','请选择角色，或输入新角色原名。'));return null;}const job=type==='party'?$('editJob').value:'';if(validate&&!(r.inputFormat==='tagged'?(job===''||(Array.from(job).length===1&&!/\s/u.test(job))):C.validJob(job))&&job!==r.job){alert(r.inputFormat==='tagged'?'新格式职业请留空或填写一个非空白 Unicode 字符。':'旧格式职业为非空白前导字符加名单内职业单字。');return null;}return{bodyRefs:C.clone(editRefs),type,newName,newServer,roleId:id,date:$('editDate').value,inputFormat:r.inputFormat||'legacy',tag:r.tag||'',time:$('editTime').value,server:$('editServer').value,body:$('editBody').value,prefix:$('boundary').value,job,marker:r.inputFormat==='tagged'?job:job?Array.from(job)[0]:''};}
 function apply(data,targets){remember();const role=data.newName?C.ensure(state,data.newName,data.newServer):C.resolve(state,data.roleId);for(const row of targets){state.corrections[row.key]={type:data.type,roleId:role?.id||null,date:row.index===index?data.date:(row.date||''),inputFormat:row.inputFormat||'legacy',tag:row.tag||'',time:row.index===index?data.time:row.time,server:row.index===index?data.server:(row.server||''),body:row.index===index?data.body:C.timed(row.raw).rest.slice(data.prefix.length),originalName:role?.name||'',prefix:data.prefix,job:data.job,marker:data.marker};if(row.index===index){state.referenceBindings??={};state.referenceBindings[row.key]={body:data.body,refs:data.bodyRefs};}}C.parse(state,state.source);mark();close();render();toast('已修正 '+targets.length+' 条记录，可撤销');}
