function roleListDialog(){modal('手动添加角色','<p>每行一个角色，服务器可省略。分隔符：<b>|</b>、<b>@</b>、<b>＠</b> 或一个实际 Tab。</p><pre>记录员\n云舟|静语庄园\nStoma@红玉海</pre><p class="hint">Tab 请通过粘贴或 TXT 导入；直接按 Tab 会切换焦点。更多规则见使用帮助。</p><textarea id="names" rows="8" aria-label="角色名列表"></textarea><div class="row"><button id="importNames">导入 UTF-8 TXT</button><button id="addNames" class="primary">添加并重新识别</button></div>');$('importNames').onclick=()=>pick('.txt',text=>$('names').value=text);$('addNames').onclick=()=>{let rows;try{rows=C.parseRoleList($('names').value);}catch(e){alert(e.message);return;}if(!rows.length)return;mutate(()=>{for(const [name,server]of rows){const role=C.ensure(state,name,server||'');if(!role.hidden)role.manual=true;}C.parse(state,state.source);});close();toast(uiText('message.691247a5','角色列表已添加，原文编辑区未解析的新改动仍保留'));};}
function configImport(text){const data=JSON.parse(text);if(data.format!=='cn-rp-log-config'||![1,2,3].includes(data.version)||!Array.isArray(data.roles))throw Error('配置格式或版本不受支持');const migration=C.migrateSettings(data.settings),settings=C.validateSettings(data.settings);for(const r of data.roles)if(!r.name||typeof r.name!=='string'||typeof r.server!=='string'||typeof r.display!=='string'||!r.display.trim()||!/^#[\da-f]{6}$/i.test(r.color))throw Error('角色配置无效');mutate(()=>{state.settings=settings;for(const r of data.roles){const role=C.ensure(state,r.name,r.server);if(!role.hidden){role.display=r.display;role.color=r.color;}}C.parse(state,state.source);});toast(uiText('message.e9a0f2c3','已按原始姓名与服务器匹配配置'));if(migration.notes.length)alert('旧配置已迁移为统一排版：\n'+migration.notes.join('\n'));}
