// Yield a frame for busy feedback, serialize expensive UI actions, and report recoverable failures.
let taskBusy=false;
async function runTask(label,fn){if(taskBusy)return;taskBusy=true;const overlay=document.createElement('div');overlay.className='taskBusy';overlay.setAttribute('role','status');overlay.textContent=label+'，请稍候…';document.body.append(overlay);document.body.setAttribute('aria-busy','true');try{await new Promise(r=>requestAnimationFrame(()=>setTimeout(r,0)));return await fn();}catch(e){toast(label+'失败：'+e.message+'。当前项目仍可保存。');}finally{overlay.remove();document.body.removeAttribute('aria-busy');taskBusy=false;}}
for(const id of ['parse','saveProject','exportWord','autoColors']){const el=$(id),handler=el.onclick;el.onclick=()=>runTask(({parse:'解析日志',saveProject:'保存项目',exportWord:'导出 Word',autoColors:'自动配色'})[id],handler);}

// Explicit draft decisions are separate from project-file save confirmation.
